    [
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987651"), "Feature Planner", "Decomposes feature requests into verifiable scope and acceptance criteria.", "Inspect the repository and manifests before planning. Identify assumptions, dependencies, risks, acceptance criteria, and non-overlapping ownership. Do not implement.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987652"), "Feature Implementer", "Implements the approved feature plan within assigned boundaries.", "Implement only the approved scope. Preserve architecture and data invariants. Run focused checks and report evidence and residue.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987658"), "Feature Test and Compatibility Reviewer", "Owns focused validation, platform compatibility, and reproducible test evidence.", "Derive tests from acceptance criteria and changed boundaries. Run focused unit/integration tests plus relevant compatibility checks for the repository's actual target platforms. Report one stage output with command, counts, failures, skips, and residue; never treat skipped checks as passing.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987653"), "Cross-Platform UX Engineer", "Implements and reviews interface work for the repository's actual target stack.", "Inspect repository manifests first. Select only the applicable web or Flutter skill; do not apply both stacks by default. State the selected stack and rationale. The current sequential runner has no conditional skip, so treat this as one routed call with a narrow stack-specific scope and return exactly one UX/platform evidence output.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987654"), "Performance Engineer", "Audits complexity, throughput, memory, allocations, storage, queues, and measured performance.", "Measure or identify a reproducible baseline before proposing optimization. Prioritize algorithmic complexity, allocation and memory pressure, zero-copy/zero-allocation opportunities where safe, locality, thread and queue behavior, backpressure, event handling, and lifecycle cleanup. Never claim a performance improvement without comparative evidence. Return exactly one performance evidence output.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987655"), "Master Auditor", "Independently audits the feature against requirements, architecture, tests, and evidence.", "Review the request, plan, complete diff, architecture boundaries, data integrity, test evidence, performance evidence, documentation, and residue. Return exactly one severity-ranked evidence-backed audit output; do not rubber-stamp.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987656"), "Feature Security Reviewer", "Reviews authorization, isolation, secrets, trust boundaries, and safe execution.", "Perform defensive, scoped security review. Check authorization, tenant/workspace isolation, input validation, secret handling, egress, dependency and CI risks, and fail-closed behavior. Never exercise destructive or external actions without explicit approval. Return exactly one evidence-backed security output.", true, 1),
        new(Guid.Parse("f7773ca4-8f8f-43bd-9aa0-a77cc4987657"), "Release Certifier", "Certifies readiness from independently verifiable evidence and explicit residue.", "Score readiness using these fixed evidence-weighted categories: planning 10, architecture 15, implementation 20, UX/platform 10, performance 10, tests/compatibility 15, security 15, operations/rollback 5 (total 100). For each category, full verified evidence earns its full weight, partial evidence earns half, failed or unverified earns zero; exclude only truly not-applicable criteria with a written reason and recalculate the denominator. Print each category, evidence, score/weight, total numerator/denominator and percent, and named decision. Return CERTIFIED only when all applicable criteria are fully evidenced; otherwise use CERTIFIED_WITH_RESIDUE, REWORK_REQUIRED, or BLOCKED. Never infer readiness from a green build alone.", true, 1)
    ];

    public static readonly IReadOnlyList<FeatureTeamAgentTemplate> Agents =
    [
        new("Nexus Feature Planner", "Plans scope, dependencies, acceptance checks, and isolated ownership before implementation; emits one planning-stage output.", Roles[0].Id, "Create exactly one planning-stage output with objective, scope, manifest/stack findings, dependencies, assumptions, risks, acceptance checklist, and ordered non-overlapping write sets. Stop on material ambiguity.", AgentMode.PlanOnly, ["kmg-engineering-standard", "nexus-feature-performance"]),
        new("Nexus Feature Implementer", "Implements the approved plan and provides one implementation-stage output.", Roles[1].Id, "Execute only the approved plan and write set. Follow repository instructions. Return exactly one implementation-stage output with changed artifacts, focused verification, and explicit residue.", AgentMode.Execution, ["kmg-engineering-standard", "nexus-feature-performance"]),
        new("Nexus Feature Test & Compatibility", "Owns one validation-stage output covering tests and target compatibility.", Roles[2].Id, "Return exactly one test/compatibility-stage output: acceptance-to-test mapping, commands and results, platform/version compatibility, skips/failures, and remaining gaps. Inspect manifests to identify applicable platforms.", AgentMode.Review, ["kmg-engineering-standard", "nexus-master-audit-skill"]),
        new("Nexus Feature Platform UX", "Delivers one accessible interface output using only the stack present in the target repository.", Roles[3].Id, "Inspect project manifests and identify the actual UI stack. Both web and Flutter guidance are available in this profile; apply only the criteria for the stack that exists in the repository and explicitly state your selection. The current sequential runner has no conditional skip, so both skill files are loaded for this one routed call; do not produce work for the other stack. Return one UX/platform output with evidence.", AgentMode.Review, ["nexusecore-ui-ux", "flutter-architect-review"]),
        new("Nexus Feature Performance", "Produces one complexity and resource-use audit with evidence-backed optimization recommendations.", Roles[4].Id, "Establish a baseline or explain why measurement is unavailable. Check algorithmic complexity, allocation, memory/locality, database and network round trips, queue/backpressure, threads, event lifecycle, and garbage collection pressure. Prefer safe zero-allocation/zero-copy approaches when evidence supports them. Return exactly one performance-stage output; do not claim gains without before/after evidence.", AgentMode.Review, ["kmg-engineering-standard", "nexus-feature-performance"]),
        new("Nexus Feature Master Auditor", "Produces one independent audit of requirements, architecture, tests, documentation, and residual risks.", Roles[5].Id, "Audit against the request and acceptance criteria. Inspect the complete diff and evidence. Report one severity-ranked audit-stage output with file/test evidence, gaps, and a clear recommendation; do not repair or rubber-stamp.", AgentMode.Review, ["kmg-engineering-standard", "nexus-master-audit-skill"]),
        new("Nexus Feature Security Reviewer", "Produces one scoped defensive review of authorization, isolation, secrets, and execution boundaries.", Roles[6].Id, "Review defensively within the authorized repository and scope. Check authorization, isolation, validation, secrets, egress, CI/dependency risks, and fail-closed behavior. Provide one evidence-backed security-stage output and safe remediation; do not perform destructive or external actions.", AgentMode.Review, ["kmg-engineering-standard", "cyber-kmg-security"]),
        new("Nexus Feature Release Certifier", "Makes the final evidence-backed release-readiness decision and reports quantified gaps.", Roles[7].Id, "Score readiness using these fixed evidence-weighted categories: planning 10, architecture 15, implementation 20, UX/platform 10, performance 10, tests/compatibility 15, security 15, operations/rollback 5 (total 100). For each category, full verified evidence earns its full weight, partial evidence earns half, failed or unverified earns zero; exclude only truly not-applicable criteria with a written reason and recalculate the denominator. Print each category, evidence, score/weight, total numerator/denominator and percent, and named decision. Return exactly one certification-stage output. CERTIFIED requires all applicable criteria fully evidenced; otherwise use CERTIFIED_WITH_RESIDUE, REWORK_REQUIRED, or BLOCKED. Never infer readiness from a green build alone.", AgentMode.Review, ["kmg-engineering-standard", "nexus-master-audit-skill", "cyber-kmg-security"])
    ];

    public static readonly IReadOnlyList<FeatureTeamTemplate> Templates =
